def vs(rows,h=('項目','内容')): return "<div class='vs'><div class='vh'><span>"+h[0]+"</span><span>"+h[1]+"</span></div>"+''.join(f"<div class='vr'><span>{a}</span><span>{b}</span></div>" for a,b in rows)+"</div>"
